export class DecoderRegistry {
    adapters = new Map();
    formats = new Map();
    disposed = false;
    register(adapter) {
        this.assertAlive();
        if (!adapter.id.trim())
            throw new Error('Decoder adapter id cannot be empty.');
        if (this.adapters.has(adapter.id))
            throw new Error(`Decoder adapter is already registered: ${adapter.id}`);
        const normalized = [...new Set(adapter.formats.map(normalizeFormat).filter(Boolean))];
        if (normalized.length === 0)
            throw new Error(`Decoder adapter ${adapter.id} requires at least one format.`);
        for (const format of normalized)
            if (this.formats.has(format))
                throw new Error(`A decoder is already registered for ${format}: ${this.formats.get(format)}`);
        this.adapters.set(adapter.id, adapter);
        for (const format of normalized)
            this.formats.set(format, adapter.id);
        let active = true;
        return () => {
            if (!active)
                return;
            active = false;
            this.adapters.delete(adapter.id);
            for (const format of normalized)
                if (this.formats.get(format) === adapter.id)
                    this.formats.delete(format);
        };
    }
    supports(format) { return this.formats.has(normalizeFormat(format)); }
    list() { return Object.freeze(Object.fromEntries([...this.formats].sort())); }
    async decode(request) {
        this.assertAlive();
        throwIfAborted(request.signal);
        const format = normalizeFormat(request.format);
        const id = this.formats.get(format);
        const adapter = id ? this.adapters.get(id) : undefined;
        if (!adapter)
            throw new Error(`No Sekai64 decoder adapter is registered for ${format}. Install an explicit optional adapter.`);
        return adapter.decode({ ...request, format });
    }
    async disposeAsync() {
        if (this.disposed)
            return;
        this.disposed = true;
        const adapters = [...this.adapters.values()].reverse();
        this.adapters.clear();
        this.formats.clear();
        for (const adapter of adapters)
            await adapter.dispose?.();
    }
    assertAlive() { if (this.disposed)
        throw new Error('DecoderRegistry is disposed.'); }
}
function normalizeFormat(value) { return value.trim().toLowerCase().replace(/^\./, ''); }
function throwIfAborted(signal) { if (signal?.aborted)
    throw signal.reason ?? new DOMException('The operation was aborted.', 'AbortError'); }